-- TESTS/bindings_checklist_points_spec.lua — the lib.nvim rows of the
-- config's BINDINGS-RUNTIME-CHECKLIST.md, run headless.
--
-- The runtime checklist (generated by `bindings.audit.checklist_lines`) is
-- meant to be ticked by hand. Ten of its rows belong to lib.nvim and need no
-- human: `<M-.>` (lastcmd), the seven `:LibLogger` subcommands, the
-- generator behind `:BindingsRuntimeChecklist`, and `:KitPreview`. They are
-- driven here through the same entry point a user would trigger (the command,
-- the default key), not through the Lua functions behind them. lib.nvim keeps
-- its own runner (TESTS/README.md, "Why lib.nvim keeps its own runner"), so
-- these are specs, not testing.nvim sheets. `:KitPreview` is covered by
-- `ui_kit_preview_command_spec.lua` and is not repeated here.

return function(H)
  local eq, ok = H.eq, H.ok

  -- ------------------------------------------------------------ :LibLogger

  local logger = require("lib.nvim.logger")
  -- logger_spec reloads the module, so a `:LibLogger` left over from an
  -- earlier spec may drive another module instance than this `require`
  -- returns. Install the command fresh against this one.
  pcall(vim.api.nvim_del_user_command, "LibLogger")
  require("lib.nvim.logger.command").install(logger)
  ok(vim.fn.exists(":LibLogger") == 2, ":LibLogger exists after install_command()")

  local file = H.tmpfile("-checklist.jsonl")
  local log = logger.new({ name = "checklistpoints", notify_level = "off", file = file })
  local was_enabled = logger.is_enabled()

  ---Run `:LibLogger <args>` and return what it notified.
  ---@param args string
  ---@return string[]
  local function run(args)
    local said = {}
    H.with_patched(vim, "notify", function(msg)
      said[#said + 1] = tostring(msg)
    end, function()
      vim.cmd("LibLogger " .. args)
    end)
    return said
  end

  ---@param needle string
  ---@return boolean
  local function in_ring(needle)
    for _, rec in ipairs(log.snapshot()) do
      if tostring(rec.msg):find(needle, 1, true) then
        return true
      end
    end
    return false
  end

  local ok_run, err = pcall(function()
    -- off: logging becomes a no-op
    run("off")
    eq(logger.is_enabled(), false, ":LibLogger off disables logging")
    log.info("while-off")
    ok(not in_ring("while-off"), ":LibLogger off: a record logged while off is not kept")

    -- on: records are kept again
    run("on")
    eq(logger.is_enabled(), true, ":LibLogger on enables logging")
    log.info("while-on")
    ok(in_ring("while-on"), ":LibLogger on: a record logged while on is kept")

    -- level: a global minimum drops records below it; no argument clears it
    run("level warn")
    log.info("below-the-level")
    log.warn("at-the-level")
    ok(not in_ring("below-the-level"), ":LibLogger level warn drops an info record")
    ok(in_ring("at-the-level"), ":LibLogger level warn keeps a warn record")
    run("level")
    log.info("level-cleared")
    ok(in_ring("level-cleared"), ":LibLogger level (no argument) clears the override")

    -- show: a scratch window with the recent records
    local before = vim.api.nvim_get_current_win()
    run("show")
    local win = vim.api.nvim_get_current_win()
    ok(win ~= before, ":LibLogger show opens a window")
    local shown = table.concat(vim.api.nvim_buf_get_lines(0, 0, -1, false), "\n")
    ok(shown:find("level-cleared", 1, true) ~= nil, ":LibLogger show lists a recent record")
    pcall(vim.api.nvim_win_close, win, true)

    -- dump: the ring buffer reaches the file sink
    local said = run("dump")
    ok(said[1] and said[1]:find("flushed", 1, true), ":LibLogger dump reports the flush")
    local written = table.concat(H.read_lines(file), "\n")
    ok(
      written:find("level-cleared", 1, true) ~= nil,
      ":LibLogger dump writes the records to the file"
    )

    -- clear: ring buffers are empty afterwards
    run("clear")
    eq(#log.snapshot(), 0, ":LibLogger clear empties the ring buffer")

    -- tags: reports the tag filters
    logger.disable_tag("checklist-noise")
    said = run("tags")
    logger.enable_tag("checklist-noise")
    ok(
      said[1] and said[1]:find("checklist-noise", 1, true) ~= nil,
      ":LibLogger tags names a disabled tag"
    )
  end)
  logger.set_level(nil)
  logger.set_enabled(was_enabled)
  if not ok_run then
    error(err, 0)
  end

  -- ------------------------------------------------- <M-.> (lastcmd)

  local lastcmd = require("lib.nvim.lastcmd")
  ok(lastcmd.setup({ experimental = true }), "lastcmd.setup({ experimental = true }) turns it on")
  local ok_key, key_err = pcall(function()
    eq(lastcmd.trigger_key(), "<M-.>", "experimental = true binds the default <M-.>")
    ok(vim.fn.maparg("<M-.>", "n") ~= "", "<M-.> is a real normal-mode keymap")

    -- pressing the default key repeats the last real command
    vim.cmd("enew")
    vim.api.nvim_buf_set_lines(0, 0, -1, false, { "abcdef" })
    vim.api.nvim_win_set_cursor(0, { 1, 0 })
    lastcmd.clear()
    local function press(keys)
      vim.api.nvim_feedkeys(vim.api.nvim_replace_termcodes(keys, true, false, true), "mtx", false)
      vim.wait(20)
    end
    press("x")
    eq(vim.api.nvim_get_current_line(), "bcdef", "x deleted one character")
    press("<M-.>")
    vim.api.nvim_feedkeys("", "x", false)
    vim.wait(20)
    eq(vim.api.nvim_get_current_line(), "cdef", "<M-.> repeated the last command")
  end)
  lastcmd.setup()
  pcall(vim.cmd, "bwipeout!")
  if not ok_key then
    error(key_err, 0)
  end
  eq(vim.fn.maparg("<M-.>", "n"), "", "lastcmd.setup() without experimental removes <M-.> again")

  -- ------------------------- :BindingsRuntimeChecklist (checklist_lines)

  -- The command lives in the config; what it writes is
  -- `bindings.audit.checklist_lines`. One plain action, one risky action and
  -- one command must land in their sections.
  local usercmd = require("lib.nvim.bindings.usercmd")
  local keymap = require("lib.nvim.bindings.keymap")
  local audit = require("lib.nvim.bindings.audit")
  usercmd.create("ChecklistSpecCmd", function() end, { desc = "checklist spec command" })
  keymap.register("checklistspec", {
    prefix = "<Plug>(checklistspec-",
    actions = {
      toggle = {
        default = "<Plug>(checklistspec-toggle)",
        rhs = function() end,
        desc = "toggle the checklist spec panel",
      },
      wipe = {
        default = "<Plug>(checklistspec-wipe)",
        rhs = function() end,
        desc = "delete every checklist spec entry",
      },
    },
  })
  local lines = audit.checklist_lines(nil)
  eq(lines[1], "# Bindings — runtime checklist", "checklist_lines starts with its title")

  ---@param needle string
  ---@return integer|nil
  local function index_of(needle)
    for i, l in ipairs(lines) do
      if l == needle then
        return i
      end
    end
  end

  local keymaps = index_of("## Keymaps")
  local surface = index_of("### checklistspec")
  local toggle = index_of(
    "- [ ] `<Plug>(checklistspec-toggle)` -- checklistspec: toggle the checklist spec panel"
  )
  local usercmds = index_of("## Usercmds")
  local cmd = index_of("- [ ] `:ChecklistSpecCmd` -- checklist spec command")
  local risky = index_of("## ⚠ Handle with care")
  local wipe = index_of(
    "- [ ] `<Plug>(checklistspec-wipe)` (checklistspec) -- checklistspec: delete every checklist spec entry"
  )
  ok(
    keymaps and surface and toggle and keymaps < surface and surface < toggle,
    "a plain action sits under its surface"
  )
  ok(usercmds and cmd and usercmds < cmd, "a command sits under ## Usercmds")
  ok(
    risky and wipe and risky < wipe,
    "a delete action sits under the risky section, not its surface"
  )
  pcall(vim.api.nvim_del_user_command, "ChecklistSpecCmd")
end
